// SPDX-License-Identifier: MPL-2.0
//
// e2ee_test.js — browser-side E2EE crypto (client/web/e2ee.js).
//
// Two kinds of assertion:
//
//   1. Cross-language vectors. tests/fixtures/e2ee-vectors.json was generated by
//      the Elixir implementation (scripts/gen-e2ee-vectors.exs) and is
//      re-derived here with WebCrypto. If the two halves of the protocol ever
//      disagree, this fails — which is the only way to notice before a client
//      ships and cannot talk to the server.
//
//   2. Behaviour the vectors cannot express: tampering, replay, epoch changes.
//
// Runs under Deno (`deno task test`) and under Node 22+ (`node --test`-less
// shim), because both expose WebCrypto.

import assert from "node:assert";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import * as E2EE from "../e2ee.js";
import { test } from "./runner.js";

const here = dirname(fileURLToPath(import.meta.url));
const vectors = JSON.parse(readFileSync(join(here, "fixtures", "e2ee-vectors.json"), "utf8"));

const hex = E2EE.fromHex;
const hexOut = E2EE.toHex;

// ---------------------------------------------------------------------------
// Is the platform capable at all?
// ---------------------------------------------------------------------------

test("E2EE.isSupported reports WebCrypto availability", () => {
  assert.strictEqual(E2EE.isSupported(), true);
});

// ---------------------------------------------------------------------------
// 1. Cross-language vectors
// ---------------------------------------------------------------------------

test("vectors: the RFC 7748 private key imports through the PKCS#8 wrapper", async () => {
  // WebCrypto has no "derive public from private" and will not import a raw
  // X25519 private key, so the wrapper is the only thing to check here: it must
  // round-trip byte-for-byte. Agreement with the fixture's public key is
  // established by the pairwise test below.
  const priv = await E2EE.importPrivateKey(hex(vectors.rfc7748_private_a), { extractable: true });
  assert.strictEqual(hexOut(await E2EE.exportPrivateKey(priv)), vectors.rfc7748_private_a);

  // A key imported without the flag must not be exportable.
  const sealed = await E2EE.importPrivateKey(hex(vectors.rfc7748_private_a));
  await assert.rejects(E2EE.exportPrivateKey(sealed));
});

test("vectors: pairwiseKey matches the Elixir implementation", async () => {
  const priv = await E2EE.importPrivateKey(hex(vectors.rfc7748_private_a));

  const got = await E2EE.pairwiseKey(
    priv,
    hex(vectors.public_b),
    vectors.room,
    vectors.epoch,
    vectors.from,
    vectors.to
  );

  assert.strictEqual(hexOut(got), vectors.pairwise_key);
});

test("vectors: pairwiseKey is symmetric", async () => {
  const privA = await E2EE.importPrivateKey(hex(vectors.rfc7748_private_a));
  const privB = await E2EE.importPrivateKey(hex(vectors.rfc7748_private_b));

  const ab = await E2EE.pairwiseKey(privA, hex(vectors.public_b), vectors.room, vectors.epoch, vectors.from, vectors.to);
  const ba = await E2EE.pairwiseKey(privB, hex(vectors.public_a), vectors.room, vectors.epoch, vectors.to, vectors.from);

  assert.deepStrictEqual(ab, ba);
  assert.strictEqual(hexOut(ab), vectors.pairwise_key);
});

test("vectors: openGroupKey opens the blob the Elixir side sealed", async () => {
  const pairwise = hex(vectors.pairwise_key);
  const wire = E2EE.decodeSealed(vectors.sealed_wire_b64);

  const opened = await E2EE.openGroupKey(
    wire,
    pairwise,
    vectors.room,
    vectors.epoch,
    vectors.from,
    vectors.to
  );

  assert.strictEqual(hexOut(opened), vectors.group_key);
});

test("vectors: deriveFrameKey matches the Elixir implementation", async () => {
  const groupKey = hex(vectors.group_key);

  for (const [counter, expected] of [
    [0, vectors.frame_key_0],
    [1, vectors.frame_key_1]
  ]) {
    const raw = await E2EE.deriveFrameKey(groupKey, vectors.epoch, counter);
    assert.strictEqual(hexOut(raw), expected, `frame key for counter ${counter}`);
  }
});

test("vectors: the protocol description in the fixture matches this module", () => {
  // Guards against a fixture regenerated with different labels while the client
  // stayed on the old ones — the failure mode the vectors exist to prevent.
  assert.ok(vectors.protocol.pairwise.includes(E2EE.CONSTANTS.LABEL_PAIRWISE));
  assert.ok(vectors.protocol.seal.includes(E2EE.CONSTANTS.LABEL_GROUP));
  assert.ok(vectors.protocol.frame.includes(E2EE.CONSTANTS.LABEL_FRAME));
  assert.strictEqual(E2EE.CONSTANTS.SEALED_BYTES, 60);
});

// ---------------------------------------------------------------------------
// 2. Sealing: round-trip, AAD binding, tampering
// ---------------------------------------------------------------------------

async function pair(roomId, epoch) {
  const a = await E2EE.generateKeypair();
  const b = await E2EE.generateKeypair();

  const aKey = await E2EE.pairwiseKey(a.privateKey, b.publicKey, roomId, epoch, "alice", "bob");
  const bKey = await E2EE.pairwiseKey(b.privateKey, a.publicKey, roomId, epoch, "bob", "alice");

  return { a, b, aKey, bKey };
}

test("seal/open round-trips the room key", async () => {
  const { aKey, bKey } = await pair("room-1", 0);
  const groupKey = E2EE.randomGroupKey();

  const wire = await E2EE.sealGroupKey(groupKey, aKey, "room-1", 0, "alice", "bob");
  assert.strictEqual(wire.length, 60);
  assert.deepStrictEqual(aKey, bKey, "both sides must derive the same pairwise key");

  const opened = await E2EE.openGroupKey(wire, bKey, "room-1", 0, "alice", "bob");
  assert.deepStrictEqual(opened, groupKey);
});

test("AAD rejects a blob replayed into another room, epoch or direction", async () => {
  const { aKey, bKey } = await pair("room-1", 0);
  const wire = await E2EE.sealGroupKey(E2EE.randomGroupKey(), aKey, "room-1", 0, "alice", "bob");

  await assert.rejects(E2EE.openGroupKey(wire, bKey, "room-2", 0, "alice", "bob"), /operation failed|decrypt/i);
  await assert.rejects(E2EE.openGroupKey(wire, bKey, "room-1", 1, "alice", "bob"), /operation failed|decrypt/i);
  await assert.rejects(E2EE.openGroupKey(wire, bKey, "room-1", 0, "bob", "alice"), /operation failed|decrypt/i);
});

test("a tampered sealed blob does not open", async () => {
  const { aKey, bKey } = await pair("room-1", 0);
  const wire = await E2EE.sealGroupKey(E2EE.randomGroupKey(), aKey, "room-1", 0, "alice", "bob");

  const tampered = Uint8Array.from(wire);
  tampered[30] ^= 0xff; // flip a ciphertext bit

  await assert.rejects(E2EE.openGroupKey(tampered, bKey, "room-1", 0, "alice", "bob"), /operation failed|decrypt/i);
});

test("the wrong pairwise key does not open a blob", async () => {
  const { aKey } = await pair("room-1", 0);
  const other = await pair("room-1", 0);

  const wire = await E2EE.sealGroupKey(E2EE.randomGroupKey(), aKey, "room-1", 0, "alice", "bob");
  await assert.rejects(E2EE.openGroupKey(wire, other.bKey, "room-1", 0, "alice", "bob"), /operation failed|decrypt/i);
});

test("malformed inputs are rejected before any crypto happens", async () => {
  const { aKey } = await pair("room-1", 0);

  await assert.rejects(E2EE.sealGroupKey(new Uint8Array(16), aKey, "r", 0, "a", "b"), RangeError);
  await assert.rejects(E2EE.sealGroupKey(E2EE.randomGroupKey(), new Uint8Array(8), "r", 0, "a", "b"), RangeError);
  await assert.rejects(E2EE.openGroupKey(new Uint8Array(59), aKey, "r", 0, "a", "b"), RangeError);
  await assert.rejects(E2EE.openGroupKey(new Uint8Array(61), aKey, "r", 0, "a", "b"), RangeError);
  assert.throws(() => E2EE.decodeSealed("AAAA"), RangeError);
});

// ---------------------------------------------------------------------------
// 3. Frames: sender attribution and replay
// ---------------------------------------------------------------------------

test("frames round-trip and are bound to sender, epoch and counter", async () => {
  const groupKey = E2EE.randomGroupKey();
  const frame = new TextEncoder().encode("opus-frame-bytes");

  const key = await E2EE.deriveSenderFrameKey(groupKey, 2, "alice", 7);
  const wire = await E2EE.encryptFrame(key, frame, "room-1", 2, "alice", 7);

  const opened = await E2EE.decryptFrame(key, wire, "room-1", 2, "alice", 7);
  assert.deepStrictEqual(opened, frame);

  // Same counters, different sender: the key differs, so this cannot decrypt.
  const bobKey = await E2EE.deriveSenderFrameKey(groupKey, 2, "bob", 7);
  await assert.rejects(E2EE.decryptFrame(bobKey, wire, "room-1", 2, "alice", 7), /operation failed|decrypt/i);

  // Right key, wrong claimed sender in the AAD.
  await assert.rejects(E2EE.decryptFrame(key, wire, "room-1", 2, "bob", 7), /operation failed|decrypt/i);

  // Right key and sender, wrong counter.
  await assert.rejects(E2EE.decryptFrame(key, wire, "room-1", 2, "alice", 8), /operation failed|decrypt/i);
});

test("sender ids separate frame keys, but any group-key holder can derive them", async () => {
  const groupKey = E2EE.randomGroupKey();

  const alice = await E2EE.deriveSenderFrameKey(groupKey, 0, "alice", 0);
  const bob = await E2EE.deriveSenderFrameKey(groupKey, 0, "bob", 0);

  assert.notDeepStrictEqual(alice, bob, "sender id must change the derivation");

  const frame = new TextEncoder().encode("forged");
  const wire = await E2EE.encryptFrame(alice, frame, "room-1", 0, "alice", 0);

  // What the separation buys: Bob's own frame key does not open a frame
  // attributed to Alice. It stops two senders' keys being confused, nothing more.
  await assert.rejects(E2EE.decryptFrame(bob, wire, "room-1", 0, "alice", 0), /operation failed|decrypt/i);
  assert.deepStrictEqual(await E2EE.decryptFrame(alice, wire, "room-1", 0, "alice", 0), frame);

  // The limitation, asserted so it cannot quietly become a claim again: Bob
  // holds the group key, so he can derive Alice's frame key himself and produce
  // a frame that is indistinguishable from hers. The boundary E2EE defends is
  // "outsiders and the server", not "members cannot impersonate each other".
  // ADR-0016 §Gaps, and the honest sentence in `deriveSenderFrameKey`.
  const derivedByBob = await E2EE.deriveSenderFrameKey(groupKey, 0, "alice", 1);
  const forged = await E2EE.encryptFrame(
    derivedByBob,
    new TextEncoder().encode("anything, as alice"),
    "room-1",
    0,
    "alice",
    1
  );
  const opened = await E2EE.decryptFrame(derivedByBob, forged, "room-1", 0, "alice", 1);
  assert.deepStrictEqual(new TextDecoder().decode(opened), "anything, as alice");
});

test("ReplayWindow accepts new counters, refuses repeats and ancient ones", () => {
  const w = new E2EE.ReplayWindow(4);

  assert.strictEqual(w.accept(0), true);
  assert.strictEqual(w.accept(1), true);
  assert.strictEqual(w.accept(0), false, "replay");
  assert.strictEqual(w.accept(5), true);
  assert.strictEqual(w.accept(2), true, "2 is still within [5 - 4 + 1, 5]");
  assert.strictEqual(w.accept(5), false, "replay of the highest");
  assert.strictEqual(w.accept(1), false, "1 has fallen out of the window");
  assert.strictEqual(w.highest, 5);

  assert.throws(() => w.accept(-1), RangeError);
  assert.throws(() => w.accept(1.5), RangeError);
});

// ---------------------------------------------------------------------------
// 4. Epoch handling
// ---------------------------------------------------------------------------

test("KeyEpoch drops key material when the epoch advances", async () => {
  const epoch = new E2EE.KeyEpoch("room-1");
  const groupKey = E2EE.randomGroupKey();

  epoch.setRoomKey(groupKey);
  assert.strictEqual(epoch.hasRoomKey(), true);

  assert.strictEqual(epoch.advanceTo(1), true);
  assert.strictEqual(epoch.hasRoomKey(), false, "a member who left still holds the old key");
  assert.strictEqual(epoch.epoch, 1);
});

test("KeyEpoch ignores a stale epoch rather than rewinding", async () => {
  const epoch = new E2EE.KeyEpoch("room-1");

  epoch.advanceTo(3);
  assert.strictEqual(epoch.advanceTo(2), false);
  assert.strictEqual(epoch.epoch, 3);
  assert.strictEqual(epoch.advanceTo(3), false);
});

test("KeyEpoch.rotate produces a fresh keypair and clears the room key", async () => {
  const epoch = new E2EE.KeyEpoch("room-1");
  epoch.setRoomKey(E2EE.randomGroupKey());

  const first = await epoch.rotate();
  const second = await epoch.rotate();

  assert.strictEqual(first.length, 32);
  assert.notDeepStrictEqual(first, second);
  assert.strictEqual(epoch.hasRoomKey(), false);
});

test("KeyEpoch.frameKey requires a room key for the current epoch", async () => {
  const epoch = new E2EE.KeyEpoch("room-1");
  await assert.rejects(epoch.frameKey("alice", 0), /no room key/);

  epoch.setRoomKey(E2EE.randomGroupKey());
  const key = await epoch.frameKey("alice", 0);
  assert.ok(key);
});

// ---------------------------------------------------------------------------
// 6. Frames on the wire: header, cryptor, encoded transforms
//
// Everything below runs against real WebCrypto and real TransformStreams. What
// it cannot prove is that a *browser* pipes RTP through them — there is no
// RTCPeerConnection here, so the attachment points are exercised with fakes
// that match the shape Chrome documents. That gap is stated in the ADR rather
// than papered over.
// ---------------------------------------------------------------------------

test("encodeFrameHeader/decodeFrameHeader round-trip sender, epoch and counter", () => {
  const bare = E2EE.encodeFrameHeader(7, 123456);
  assert.strictEqual(bare.length, E2EE.CONSTANTS.FRAME_HEADER_BYTES);

  const header = E2EE.encodeFrameHeader(7, 123456, "alice");
  assert.strictEqual(header.length, E2EE.CONSTANTS.FRAME_HEADER_BYTES + "alice".length);

  const parsed = E2EE.decodeFrameHeader(new Uint8Array([...header, 0xaa, 0xbb]));
  assert.strictEqual(parsed.version, 1);
  assert.strictEqual(parsed.senderId, "alice");
  assert.strictEqual(parsed.epoch, 7);
  assert.strictEqual(parsed.counter, 123456);
  assert.deepStrictEqual(parsed.body, new Uint8Array([0xaa, 0xbb]));

  // A frame with no sender id parses as such rather than inventing one.
  assert.strictEqual(E2EE.decodeFrameHeader(bare).senderId, null);
});

test("decodeFrameHeader refuses a short frame and an unknown version", () => {
  assert.throws(() => E2EE.decodeFrameHeader(new Uint8Array([1, 0, 0])), /shorter than its header/);

  const bumped = E2EE.encodeFrameHeader(0, 0);
  bumped[0] = 2;
  assert.throws(() => E2EE.decodeFrameHeader(bumped), /unsupported frame version 2/);
});

test("frame counters and epochs must be uint32", () => {
  assert.throws(() => E2EE.encodeFrameHeader(-1, 0), /uint32/);
  assert.throws(() => E2EE.encodeFrameHeader(0, 2 ** 32), /uint32/);
  assert.throws(() => E2EE.encodeFrameHeader(1.5, 0), /uint32/);
});

test("sealFrame embeds its header and opens with the derived key", async () => {
  const groupKey = E2EE.randomGroupKey();
  const plaintext = new Uint8Array([1, 2, 3, 4, 5, 6, 7, 8]);

  const wire = await E2EE.sealFrame(groupKey, plaintext, "room-1", 3, "alice", 42);

  const parsed = E2EE.decodeFrameHeader(wire);
  assert.strictEqual(parsed.senderId, "alice");
  assert.strictEqual(parsed.epoch, 3);
  assert.strictEqual(parsed.counter, 42);
  // 12-byte IV + 16-byte tag + 8 bytes of payload, on top of the header.
  assert.strictEqual(
    wire.length,
    E2EE.CONSTANTS.FRAME_HEADER_BYTES + "alice".length + 12 + 16 + plaintext.length
  );

  const key = await E2EE.deriveSenderFrameKey(groupKey, 3, "alice", 42);
  const opened = await E2EE.decryptFrame(key, parsed.body, "room-1", 3, "alice", 42);
  assert.deepStrictEqual(opened, plaintext);
});

function pairOfCryptors() {
  const groupKey = E2EE.randomGroupKey();
  const aliceEpochs = new E2EE.KeyEpoch("room-1");
  const bobEpochs = new E2EE.KeyEpoch("room-1");
  aliceEpochs.setRoomKey(groupKey);
  bobEpochs.setRoomKey(groupKey);

  return {
    alice: new E2EE.FrameCryptor({ epochs: aliceEpochs, roomId: "room-1", localId: "alice", remoteId: "bob" }),
    bob: new E2EE.FrameCryptor({ epochs: bobEpochs, roomId: "room-1", localId: "bob", remoteId: "alice" })
  };
}

test("FrameCryptor seals and opens between two peers", async () => {
  const { alice, bob } = pairOfCryptors();
  const plaintext = new Uint8Array([9, 9, 9]);

  const wire = await alice.seal(plaintext);
  assert.deepStrictEqual(await bob.open(wire), plaintext);

  // Counters advance independently per direction.
  assert.strictEqual(alice.sentCount, 1);
  assert.strictEqual(bob.sentCount, 0);
});

test("FrameCryptor refuses a replay, a foreign sender and a tampered frame", async () => {
  const { alice, bob } = pairOfCryptors();
  const wire = await alice.seal(new Uint8Array([1]));

  assert.deepStrictEqual(await bob.open(wire), new Uint8Array([1]));
  await assert.rejects(bob.open(wire), /replay or outside the window/);

  // A mesh connection knows who is on the other end, so a frame that claims a
  // different speaker is refused by name — before any crypto.
  const { alice: alice2, bob: bob2 } = pairOfCryptors();
  const wire2 = await alice2.seal(new Uint8Array([2]));
  await assert.rejects(bob2.open(wire2, "carol"), /frame is from alice, expected carol/);

  // Byte-flip in the ciphertext.
  const { alice: alice3, bob: bob3 } = pairOfCryptors();
  const wire3 = await alice3.seal(new Uint8Array([3, 3, 3]));
  wire3[wire3.length - 1] ^= 0x01;
  await assert.rejects(bob3.open(wire3), /OperationError|decrypt/i);
});

test("a frame that fails to decrypt does not consume its counter", async () => {
  const { alice, bob } = pairOfCryptors();
  const good = await alice.seal(new Uint8Array([7, 7]));

  const corrupt = good.slice();
  corrupt[corrupt.length - 1] ^= 0xff;
  await assert.rejects(bob.open(corrupt));

  // The genuine frame still opens: the failed attempt did not spend counter 0.
  assert.deepStrictEqual(await bob.open(good), new Uint8Array([7, 7]));
});

test("FrameCryptor refuses frames from another epoch", async () => {
  const groupKey = E2EE.randomGroupKey();
  const aliceEpochs = new E2EE.KeyEpoch("room-1");
  const bobEpochs = new E2EE.KeyEpoch("room-1");
  aliceEpochs.setRoomKey(groupKey);
  bobEpochs.setRoomKey(groupKey);

  const alice = new E2EE.FrameCryptor({ epochs: aliceEpochs, roomId: "room-1", localId: "alice", remoteId: "bob" });
  const bob = new E2EE.FrameCryptor({ epochs: bobEpochs, roomId: "room-1", localId: "bob", remoteId: "alice" });

  const epochZero = await alice.seal(new Uint8Array([4]));
  assert.deepStrictEqual(await bob.open(epochZero), new Uint8Array([4]));

  // Something changed the membership: Bob's tracker moves to epoch 1 and his
  // cryptor drops its replay window.
  bobEpochs.advanceTo(1);
  bob.reset();

  // A frame sealed under epoch 0 is refused by name, not by a crypto error.
  await assert.rejects(bob.open(epochZero), /from epoch 0, current is 1/);
});

test("senderTransform and receiverTransform carry frames between stream pairs", async () => {
  const { alice, bob } = pairOfCryptors();
  const plaintext = new Uint8Array([0xde, 0xad, 0xbe, 0xef]);

  // The sender's readable feeds a transform whose output the browser sends.
  const senderIn = new TransformStream();
  const senderOut = new TransformStream();
  senderIn.readable.pipeThrough(E2EE.senderTransform(alice)).pipeTo(senderOut.writable);

  const receiverIn = new TransformStream();
  const receiverOut = new TransformStream();
  receiverIn.readable.pipeThrough(E2EE.receiverTransform(bob)).pipeTo(receiverOut.writable);

  const senderWriter = senderIn.writable.getWriter();
  const senderReader = senderOut.readable.getReader();
  const receiverWriter = receiverIn.writable.getWriter();
  const receiverReader = receiverOut.readable.getReader();

  await senderWriter.write({ data: plaintext });
  const sealed = await senderReader.read();
  assert.notDeepStrictEqual(new Uint8Array(sealed.value.data), plaintext);

  await receiverWriter.write(sealed.value);
  const opened = await receiverReader.read();
  assert.deepStrictEqual(new Uint8Array(opened.value.data), plaintext);
});

test("a frame the transform cannot seal is dropped, never forwarded in the clear", async () => {
  const errors = [];
  const broken = {
    seal: async () => {
      throw new Error("key unavailable");
    }
  };

  const input = new TransformStream();
  const output = new TransformStream();
  input.readable
    .pipeThrough(E2EE.senderTransform(broken, { onError: e => errors.push(e) }))
    .pipeTo(output.writable);

  const writer = input.writable.getWriter();
  const reader = output.readable.getReader();

  await writer.write({ data: new Uint8Array([1, 2, 3]) });
  await writer.close();

  assert.deepStrictEqual(await reader.read(), { value: undefined, done: true });
  assert.strictEqual(errors.length, 1);
  assert.match(errors[0].message, /key unavailable/);
});

test("attachFrameCrypto fails closed when encoded transforms are unavailable", () => {
  const fakePc = {
    getSenders: () => [{}],
    getReceivers: () => [{ createEncodedStreams: () => null }]
  };
  const cryptor = pairOfCryptors().alice;

  const result = E2EE.attachFrameCrypto(fakePc, { cryptor });

  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.results.length, 2);
  for (const r of result.results) {
    assert.strictEqual(r.ok, false);
    assert.match(r.reason, /encoded-transform-unavailable|no transceivers/);
  }
});

test("attachFrameCrypto wires a fake peer connection end to end", async () => {
  const { alice, bob } = pairOfCryptors();
  const plaintext = new Uint8Array([42, 43, 44]);

  function endpoint() {
    const inbound = new TransformStream(); // peer → encryptor
    const outbound = new TransformStream(); // encryptor → peer
    return {
      endpoint: { createEncodedStreams: () => ({ readable: inbound.readable, writable: outbound.writable }) },
      writer: inbound.writable.getWriter(),
      reader: outbound.readable.getReader()
    };
  }

  const senderSide = endpoint();
  const receiverSide = endpoint();

  const sendResult = E2EE.attachFrameCrypto(
    { getSenders: () => [senderSide.endpoint], getReceivers: () => [] },
    { cryptor: alice, role: "sender" }
  );
  const recvResult = E2EE.attachFrameCrypto(
    { getSenders: () => [], getReceivers: () => [receiverSide.endpoint] },
    { cryptor: bob, role: "receiver" }
  );

  assert.strictEqual(sendResult.ok, true);
  assert.strictEqual(recvResult.ok, true);

  await senderSide.writer.write({ data: plaintext });
  const sealed = await senderSide.reader.read();
  assert.notDeepStrictEqual(new Uint8Array(sealed.value.data), plaintext);

  await receiverSide.writer.write(sealed.value);
  const opened = await receiverSide.reader.read();
  assert.deepStrictEqual(new Uint8Array(opened.value.data), plaintext);
});

test("an SFU receive path attributes frames by their header, not by connection", async () => {
  // One receive path, many speakers: this is what an SFU looks like to a
  // client, and it is why the sender id is in the frame.
  const groupKey = E2EE.randomGroupKey();
  const listenerEpochs = new E2EE.KeyEpoch("room-1");
  listenerEpochs.setRoomKey(groupKey);

  const alice = new E2EE.FrameCryptor({ epochs: listenerEpochs, roomId: "room-1", localId: "alice", remoteId: null });
  const bob = new E2EE.FrameCryptor({ epochs: listenerEpochs, roomId: "room-1", localId: "bob", remoteId: null });
  const carol = new E2EE.FrameCryptor({ epochs: listenerEpochs, roomId: "room-1", localId: "carol", remoteId: null });

  const fromAlice = await alice.seal(new Uint8Array([1]));
  const fromBob = await bob.seal(new Uint8Array([2]));

  assert.deepStrictEqual(await carol.open(fromAlice), new Uint8Array([1]));
  assert.deepStrictEqual(await carol.open(fromBob), new Uint8Array([2]));

  // Replay windows are per speaker: Alice's counter 0 and Bob's counter 0 are
  // both accepted, because they are different streams.
  await assert.rejects(carol.open(fromAlice), /replay or outside the window/);
});

test("a frame whose header claims another speaker does not decrypt", async () => {
  const { alice, bob } = pairOfCryptors();
  const wire = await alice.seal(new Uint8Array([4, 2]));

  // Rewrite the sender id in the header to "carol" (same length as "alice") and
  // open it with the pin lifted, as an SFU receiver would: the header now says
  // carol, so the key derived is carol's, and the AAD sealed into the frame
  // says alice. That mismatch is what makes the attribution un-forgeable.
  const forged = wire.slice();
  forged.set(new TextEncoder().encode("carol"), 2);

  await assert.rejects(bob.open(forged, null), /OperationError|decrypt/i);
});
